     * Coverage: vertices == null -> getTree(false).getCut() == null.
     */
    @Test
    public void testGetVertices_NullVerticesAndNullCut() {
        BSPTree<Euclidean2D> mockTree = mock(BSPTree.class);
        when(polygonsSet.getTree(false)).thenReturn(mockTree);
        when(mockTree.getCut()).thenReturn(null);

        Vector2D[][] result = polygonsSet.getVertices();

        assertNotNull(result);
        assertEquals(0, result.length);
    }

